// splitTemplate trims only the outside whitespace. Quoted strings inside a
// template are left untouched.
func splitTemplate(input string) (prefix, body, suffix string, hasTemplate bool, err error) {
	trimmed := strings.TrimSpace(input)
	start := strings.Index(trimmed, "{{")
	if start < 0 {
		if strings.Contains(trimmed, "}}") {
			return "", "", "", false, malformedTemplate(input)
		}
		return "", trimmed, "", false, nil
	}
	prefix = trimmed[:start]
	if strings.Contains(prefix, "}}") {
		return "", "", "", false, malformedTemplate(input)
	}
	quote := byte(0)
	escaped := false
	end := -1
	for i := start + 2; i < len(trimmed)-1; i++ {
		c := trimmed[i]
		if quote != 0 {
			if escaped {
				escaped = false
			} else if c == '\\' && quote != '`' {
				escaped = true
			} else if c == quote {
				quote = 0
			}
			continue
		}
		if c == '"' || c == '\'' || c == '`' {
			quote = c
			continue
		}
		if c == '}' && trimmed[i+1] == '}' {
			end = i
			break
		}
	}
	if end < 0 {
		return "", "", "", false, malformedTemplate(input)
	}
	suffix = trimmed[end+2:]
	if strings.Contains(suffix, "{{") || strings.Contains(suffix, "}}") {
		return "", "", "", false, malformedTemplate(input)
	}
	body = strings.TrimSpace(trimmed[start+2 : end])
	if body == "" {
		return "", "", "", false, malformedTemplate(input)
	}
	return prefix, body, suffix, true, nil
}

func malformedTemplate(input string) error {
	return trace.BadParameter("malformed template usage in %q: expected one {{expression}}", input)
}

